parameters.jsCode:
// Sanitizer Agent v2.1 - CG-018 Extended Blocklist
// ================================================================================
// This node validates and sanitizes LLM output before sending to client.
// v2.1 additions: RAG/embedding terms, agent names, decision codes, legal patterns
// ================================================================================

const data = $('Decision Engine v2').first().json;
let sanitizerOut = { client_comment: '', client_summary_line: '', safety: { pass: true, leaked_terms: [] } };

try {
    const content = $json.choices?.[0]?.message?.content || '{}';
    sanitizerOut = JSON.parse(content);
} catch (e) {
    console.log('Sanitizer parse error', e);
}

// LEAKAGE GUARD - Extended blocklist v2.1 (Gap 8 + CG-018)
const blocklist = [
    // === Base terms (v1.0 - existing) ===
    'playbook', 'policy', 'policyspec', 'rule_id', 'rulename',
    'aceptable', 'inaceptable', 'acceptable', 'unacceptable',
    'threshold', 'confidence', 'anchor_conf', 'coverage',
    'escalate', 'escalation', 'routing', 'gating',
    'policyowner', 'amazonlegal', 'legal team', 'despacho',
    'internal', 'guidance', 'standard_position',
    'variation', 'variationset', 'paranoid', 'valuator', 'sanitizer',
    'source_reference', 'exact_text', 'mode_strict', 'mode_enumerated',
    'block_export', 'auto_pass', 'auto_redline', 'observation',
    'evidence_span', 'anchor_confidence', 'confidence_overall',
    'rule_candidate', 'policy_judgment', 'family_pack', 'v2026',

    // === CG-018 New terms (v2.1) ===
    // RAG/Embedding system
    'rag', 'embedding', 'embeddings', 'similarity', 'vector', 'vectorstore',
    'semantic_search', 'lightrag', 'supabase', 'pinecone', 'openai',

    // Agent names and components
    'agent', 'router', 'classifier', 'decisor', 'decision_engine',
    'keyword_v5', 'hybrid_router', 'family_pack',

    // Decision codes (internal)
    'AUTO_PASS', 'APPROVE_WITH_NOTES', 'ESCALATE_HUMAN', 'BLOCK_EXPORT',
    'NEEDS_REVIEW', 'Compliant', 'AcceptableDeviation', 'UnacceptableDeviation',

    // Pattern matching terms
    'deviation', 'red_flag', 'red flag', 'pattern_matched',
    'must_have', 'must-have', 'keyword_match', 'tier1', 'tier2', 'tier3',

    // Technical/System terms
    'json_schema', 'validation_passed', 'processing_time', 'routing_method',
    'top_matches', 'coverage_confidence', 'leak_score',

    // Legal analysis terms (should not leak)
    'few-shot', 'fewshot', 'grounding', 'semantic matching',
    'mode_enumerated_deviations', 'mode_strict', 'priority_critical',

    // Internal references
    '_internal', '_sanitized', 'clause_reviews_internal', 'paranoidOutput',
    'valuatorOutput', 'decisorOutput', 'playbookSpec', 'policySpec',

    // Specific family/pattern IDs
    'IndemnityProdCo', 'IndemnityAmazon', 'PaymentCredits', 'Insurance',
    'LiabilityLimitation', 'RepsProdCo', 'IndemnityProcedures'
];

const textToCheck = (
    (sanitizerOut.client_summary_line || '') + ' ' +
    (sanitizerOut.client_comment || '')
).toLowerCase();

const detectedTerms = blocklist.filter(term => textToCheck.includes(term.toLowerCase()));
const leakScore = detectedTerms.length / blocklist.length;
const safetyPass = detectedTerms.length === 0;

// Override decision if leakage detected
let decision = data.decisorOutput.decision;
let blockExport = data.decisorOutput.escalation?.block_export || false;
if (!safetyPass) {
    decision = 'BLOCK_EXPORT';
    blockExport = true;
}

// Build internal result for clause_reviews_internal table
const internalResult = {
    run_id: data.run_id,
    clause_instance_id: data.clause_instance_id,
    detected_family: data.detected_family,
    rule_id: data.policySpec?.rule_id || null,
    analysis_mode: data.policySpec?.analysis_mode || 'MODE_ENUMERATED_DEVIATIONS',
    observations: data.paranoidOutput || {},
    observations_count: data.paranoidOutput?.observations?.length || data.paranoidOutput?.summary?.counts?.total || 0,
    final_status: data.valuatorOutput?.final_status || 'Unknown',
    proposed_changes: data.valuatorOutput?.proposed_changes || [],
    anchor_confidence: data.decisorOutput?.anchor_confidence || 0,
    confidence_overall: data.decisorOutput?.confidence_overall || 0,
    decision: decision,
    escalation_recommended: data.decisorOutput?.escalation?.recommended || false,
    escalation_reason: data.decisorOutput?.escalation?.reason || null,
    block_export: blockExport,
    validation_passed: true,
    processing_time_ms: 0,
    routing_method: data._routing_method || data.routing_method || null,
    routing_confidence: data._keyword_confidence || data.routing_confidence || 0,
    keyword_confidence: data._keyword_confidence || 0,
    top_matches: data._matches || null,
    // CG-018: Track blocklist version and leakage
    blocklist_version: 'v2.1',
    leaked_terms_count: detectedTerms.length
};

// Build sanitized result for sanitizer_outputs table
const sanitizedResult = {
    run_id: data.run_id,
    clause_instance_id: data.clause_instance_id,
    client_summary_line: sanitizerOut.client_summary_line || '',
    client_comment: sanitizerOut.client_comment || '',
    client_status: data.decisorOutput?.client_state || 'NEEDS_REVIEW',
    safety_pass: safetyPass,
    blocked_terms_detected: detectedTerms,
    leak_score: leakScore,
    proposed_changes_client: (data.valuatorOutput?.proposed_changes || []).map(c => ({
        op_type: c.change_type || c.op_type,
        original_text: c.original_text,
        replacement_text: c.replacement_text
    }))
};

// Combined for response
const responseResult = {
    clause_instance_id: data.clause_instance_id,
    clause_id: data.clause_id,
    document_id: data.document_id,
    run_id: data.run_id,
    detected_family: data.detected_family,
    client_state: data.decisorOutput?.client_state,
    client_comment: sanitizerOut.client_comment,
    client_summary_line: sanitizerOut.client_summary_line,
    decision: decision,
    safety_pass: safetyPass,
    completed_at: new Date().toISOString(),
    _internal: internalResult,
    _sanitized: sanitizedResult
};

return [{ json: responseResult }];

// Detect potential routing failures for logging
const data = $json;

// Define variables from $json to avoid bare reference errors
const detected_family = data.detected_family || data._internal?.detected_family || 'OtherUnknown';
const routerOutput = data.routerOutput || data._internal || {};
const internalData = data._internal || {};

// Detect failure conditions
const failures = [];

// 1. Low confidence routing (< 0.65)
const routingConf = routerOutput.confidence || routerOutput.routing_confidence || 0;
if (routingConf > 0 && routingConf < 0.65) {
  failures.push({
    type: 'low_confidence',
    agent: 'router',
    confidence: routingConf,
    route: detected_family,
    method: routerOutput._routing_method || routerOutput.routing_method || 'unknown'
  });
}

// 2. LLM fallback when keyword should have matched
const routingMethod = routerOutput._routing_method || routerOutput.routing_method || '';
const keywordConf = routerOutput._keyword_confidence || 0;
if (routingMethod === 'LLM' && keywordConf > 0.4) {
  failures.push({
    type: 'keyword_fallback',
    agent: 'router',
    confidence: routingConf,
    keyword_conf: keywordConf
  });
}

// 3. OtherUnknown classification (potentially missed family)
if (detected_family === 'OtherUnknown') {
  failures.push({
    type: 'unknown_classification',
    agent: 'router',
    confidence: routingConf,
    clause_text_preview: (data.clause_text || '').substring(0, 200)
  });
}

// 4. Escalation due to low anchor confidence
const anchorConf = internalData.anchor_confidence || 0;
if (internalData.escalation_recommended && anchorConf < 0.7) {
  failures.push({
    type: 'low_anchor_confidence',
    agent: 'decision_engine',
    confidence: anchorConf,
    anchor_reason: internalData.escalation_reason || 'unknown'
  });
}

// Build failure payload if any failures detected
const hasFailures = failures.length > 0;
const failurePayload = hasFailures ? {
  run_id: data.run_id || '',
  clause_instance_id: data.clause_instance_id || '',
  agent_name: failures[0].agent,
  failure_type: failures[0].type,
  original_input: (data.clause_text || '').substring(0, 1000),
  actual_output: JSON.stringify(routerOutput),
  confidence: failures[0].confidence,
  route_assigned: detected_family
} : null;

return [{
  json: {
    ...data,
    _failure_detection: {
      has_failures: hasFailures,
      failures: failures,
      payload: failurePayload
    }
  }
}];

// CG-007: Parse LLM Classification Result
const input = $input.item.json;

// Get data from previous nodes
const clauseData = $('Hybrid Router (Stage 1)').first().json;
const llmResponse = input.choices?.[0]?.message?.content || '';
const keywordFamily = clauseData.detected_family;
const keywordConfidence = clauseData.routing_confidence || 0;

// Parse LLM response
let llmResult = { family: 'OtherUnknown', confidence: 0.5, reasoning: 'Parse failed' };
try {
    const jsonMatch = llmResponse.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
        llmResult = JSON.parse(jsonMatch[0]);
    }
} catch (e) {
    // Fallback to keyword
}

// Conflict resolution
const CANONICAL_FAMILIES = ["PaymentCredits", "ThirdPartyCredits", "RepsProdCo", "RepsAmazon",
    "IndemnityProdCo", "IndemnityAmazon", "IndemnityProcedures", "LiabilityLimitation",
    "InjunctiveReliefWaiver", "TerminationRights", "TerminationConsequences", "Confidentiality",
    "DataProtection", "GoverningLaw", "DisputeResolution", "ForceMajeure", "Insurance",
    "RightsGrant", "RightsReversion", "AuditRights", "Publicity", "Assignment", "ServicesScope",
    "SurvivalRemedies", "AmazonControl", "GeneralProvisions", "ConditionsPrecedent", "Definitions",
    "Parties", "OtherUnknown"];

if (!CANONICAL_FAMILIES.includes(llmResult.family)) {
    llmResult.family = 'OtherUnknown';
}

const llmConf = llmResult.confidence || 0.5;
let finalFamily = llmResult.family;
let finalConfidence = llmConf;
let method = 'llm_semantic';

// Resolution rules
if (keywordFamily === llmResult.family) {
    method = 'keyword+llm_agree';
    finalConfidence = Math.max(keywordConfidence, llmConf);
} else if (llmConf >= 0.85) {
    method = 'llm_semantic';
} else if (keywordConfidence >= 0.90 && llmConf < 0.80) {
    finalFamily = keywordFamily;
    finalConfidence = keywordConfidence;
    method = 'keyword_override';
}

return {
    json: {
        ...clauseData,
        detected_family: finalFamily,
        routing_confidence: finalConfidence,
        routing_method: method,
        _llm_result: llmResult,
        _keyword_family: keywordFamily,
        _keyword_confidence: keywordConfidence
    }
};

// CG-010: Auto-Redline Generator v1 (Suggest-Only)
// PO-mandated: CRITICAL families only, source_reference required

const CRITICAL_FAMILIES = [
    'IndemnityProdCo',
    'IndemnityAmazon',
    'IndemnityProcedures',
    'LiabilityLimitation',
    'TerminationRights',
    'TerminationConsequences',
    'RightsGrant',
    'RightsReversion',
    'AuditRights'
];

const TH_ANCHOR = 0.75; // Minimum anchor confidence threshold

/**
 * Generate redline suggestions for a clause
 * @param {Object} input - Clause data with valuator output
 * @returns {Array} - suggestions array
 */
function generateSuggestions(input) {
    const {
        clause_text,
        family,
        valuator_status,
        paranoid_observations,
        policy_spec
    } = input;

    // Only CRITICAL families get suggestions in v1
    if (!CRITICAL_FAMILIES.includes(family)) {
        return [];
    }

    const suggestions = [];

    // Logic by Valuator status
    switch (valuator_status) {
        case 'Compliant':
            // No suggestions needed
            return [];

        case 'AcceptableDeviation':
            // Optional suggestions (requires_review = false)
            if (policy_spec?.acceptable_variations?.length > 0) {
                const suggestion = buildSuggestion({
                    clause_text,
                    policy_spec,
                    requires_review: false,
                    rationale: 'Optional alignment with standard position'
                });
                if (suggestion) suggestions.push(suggestion);
            }
            break;

        case 'UnacceptableDeviation':
            // Mandatory suggestions (requires_review = true)
            const suggestion = buildSuggestion({
                clause_text,
                policy_spec,
                requires_review: true,
                rationale: 'Clause deviates from acceptable range - review required'
            });
            if (suggestion) suggestions.push(suggestion);
            break;

        case 'NotCoveredByPlaybook':
            // Comment only, no suggestions
            return [];

        default:
            return [];
    }

    return suggestions;
}

/**
 * Build a single suggestion with anchor detection
 */
function buildSuggestion({ clause_text, policy_spec, requires_review, rationale }) {
    if (!policy_spec?.standard_position) {
        return null;
    }

    // Find anchor in clause text
    const anchor = findAnchor(clause_text, policy_spec.unacceptable_patterns || []);

    if (!anchor || anchor.confidence < TH_ANCHOR) {
        // Cannot anchor reliably - skip suggestion
        return null;
    }

    return {
        op_type: 'REPLACE',
        anchor: {
            quote: anchor.text,
            offsets: { start: anchor.start, end: anchor.end },
            anchor_confidence: anchor.confidence
        },
        replacement_text: standardPositionText,
        source_reference: {
            source_type: 'STANDARD_POSITION',
            exact_text: standardPositionText
        },
        rationale,
        requires_review
    };
}

/**
 * Find anchor text in clause based on unacceptable patterns
 */
function findAnchor(clause_text, unacceptable_patterns) {
    const lowerClause = clause_text.toLowerCase();

    for (const pattern of unacceptable_patterns) {
        // Simple pattern matching - can be enhanced with regex
        const patternText = pattern.pattern || '';
        const lowerPattern = patternText.toLowerCase();

        const startIdx = lowerClause.indexOf(lowerPattern);
        if (startIdx !== -1) {
            const endIdx = startIdx + patternText.length;
            // Extract actual text with original casing
            const matchedText = clause_text.substring(startIdx, endIdx);

            return {
                text: matchedText,
                start: startIdx,
                end: endIdx,
                confidence: 0.85 // Pattern match confidence
            };
        }
    }

    // Fallback: no anchor found
    return null;
}

/**
 * Validate suggestion meets no-new-text rule
 */
function validateNoLeakage(suggestion) {
    if (!suggestion.source_reference?.exact_text) {
        return { valid: false, reason: 'Missing source_reference.exact_text' };
    }

    // Check replacement comes from source
    const sourceText = suggestion.source_reference.exact_text;
    const replacement = suggestion.replacement_text;

    if (replacement && !sourceText.includes(replacement.substring(0, 50))) {
        return { valid: false, reason: 'Replacement text not found in source' };
    }

    return { valid: true };
}

// n8n Code Node wrapper
// Get data from Parse Valuator with correct field names
const prevData = $input.first().json;

// Extract standard text from policySpec (handles object or string)
const getStandardText = (sp) => {
  if (!sp) return '';
  if (typeof sp === 'string') return sp;
  return sp.text || sp.summary || JSON.stringify(sp);
};
const standardPositionText = getStandardText(prevData.policySpec?.standard_position);

const family = prevData.detected_family || 'OtherUnknown';
const clause_text = prevData.clause_text || '';
const valuator_status = prevData.valuatorOutput?.final_status || 'Unknown';
const policy_spec = prevData.policySpec || {};

// Build input with correct mapping
const input = { clause_text, family, valuator_status, policy_spec };
const suggestions = generateSuggestions(input);

// Validate all suggestions
const validatedSuggestions = suggestions.filter(s => {
    const validation = validateNoLeakage(s);
    if (!validation.valid) {
        console.log(`Blocked suggestion: ${validation.reason}`);
        return false;
    }
    return true;
});

return [{
    json: {
        ...prevData,
        family: family,
        suggestions: validatedSuggestions,
        suggestion_count: validatedSuggestions.length
    }
}];

/**
 * Discovery Mode Check Node
 * Position: After "IF LLM Required" outputs merge
 * Purpose: Determine if Discovery Mode should activate for unknown/low-confidence clauses
 */

const clauseData = $json;
const routingConfidence = clauseData._keyword_confidence || 0;
const detectedFamily = clauseData.detected_family;
const needsLLM = clauseData.needs_llm_fallback;

// Determine if Discovery Mode should activate
const activateDiscovery =
    detectedFamily === 'OtherUnknown' ||
    routingConfidence < 0.50 ||
    (needsLLM && routingConfidence < 0.40);

// Known families with playbook specs
const KNOWN_FAMILIES = [
    // CRITICAL
    'IndemnityProdCo', 'IndemnityAmazon', 'IndemnityProcedures',
    'RepsProdCo', 'RightsGrant', 'RightsReversion',
    'LiabilityLimitation', 'InjunctiveReliefWaiver',
    'TerminationRights', 'TerminationConsequences',
    'PaymentCredits', 'ThirdPartyCredits',
    'SurvivalRemedies', 'AmazonControl', 'Assignment',
    'MoralRights', 'AIPolicy',

    // HIGH
    'DisputeResolution', 'Confidentiality', 'Insurance', 'ForceMajeure',
    'CreativeControl', 'KeyPersons', 'DeliveryAcceptance', 'BudgetOverages',

    // MEDIUM
    'DataProtection', 'ServicesScope', 'AuditRights', 'TaxProvisions',
    'Publicity', 'PowerOfAttorney', 'ConditionsPrecedent', 'StandardTerms'
];

const hasPlaybookSpec = KNOWN_FAMILIES.includes(detectedFamily);
const useDiscoveryMode = activateDiscovery || !hasPlaybookSpec;

// Determine discovery reason
let discoveryReason = null;
if (useDiscoveryMode) {
    if (!hasPlaybookSpec) {
        discoveryReason = 'NO_PLAYBOOK_SPEC';
    } else if (detectedFamily === 'OtherUnknown') {
        discoveryReason = 'UNKNOWN_FAMILY';
    } else {
        discoveryReason = 'LOW_CONFIDENCE';
    }
}

return [{
    json: {
        ...clauseData,
        _use_discovery_mode: useDiscoveryMode,
        _discovery_reason: discoveryReason,
        _routing_confidence: routingConfidence,
        _has_playbook_spec: hasPlaybookSpec
    }
}];

